function parseClock(s){const m=s.trim().match(/(\d{1,2}):?(\d{2})?\s*(AM|PM)/i);if(!m)return null;let h=Number(m[1]);const ap=m[3].toUpperCase();if(h===12)h=0;if(ap==="PM")h+=12;return h;}
function parseClientText(text){const fields={};text.split(/\r?\n/).forEach(line=>{const i=line.indexOf(':');if(i>0){const k=line.slice(0,i).trim().toLowerCase(),v=line.slice(i+1).trim();fields[k]=v;}});const name=fields.name||'',contact=fields.contact||'',dateText=fields.date||'',timeText=fields.time||'',playersText=fields.players||'',coaching=fields.coaching||'',rateText=fields.rate||'';if(!name||!dateText||!timeText)return{error:'Could not read Name, Date, or Time. Paste the full message generated by the client page.'};const dt=new Date(dateText);if(Number.isNaN(dt.getTime()))return{error:'I found the date line but could not understand the date.'};const tm=timeText.match(/(.+?)\s*-\s*(.+?)(?:\s*\(|$)/);if(!tm)return{error:'I could not understand the time range.'};const st=parseClock(tm[1]),en=parseClock(tm[2]);if(st===null||en===null)return{error:'I could not convert the start/end time.'};const players=Number(playersText)||(/1-on-1/i.test(coaching)?1:/partner|2[–-]3|2 players/i.test(coaching)?2:/group|4[–-]8/i.test(coaching)?4:1);const rateMatch=rateText.replace(/,/g,'').match(/₱?\s*(\d+(?:\.\d+)?)/);const rate=rateMatch?Number(rateMatch[1]):standardRate(players);return{name,contact:contact==='Not provided'?'':contact,date:dateStr(dt),start:st,end:en,players,coaching:coaching||coachingType(players),rate,source:text};}
$("parseBtn").onclick=async()=>{const text=$("pasteInquiry").value.trim();const res=$("parseResult");$("savePendingBtn").disabled=true;parsedInquiry=null;if(!text){res.className='parse-result error';res.textContent='Paste a client message first.';return;}const p=parseClientText(text);if(p.error){res.className='parse-result error';res.textContent=p.error;return;}parsedInquiry=p;const bad=await conflictsFor(p.date,p.start,p.end);$("bookingDate").value=p.date;await loadBookingAvailability();$("bookingClient").value=p.name;$("bookingContact").value=p.contact;$("participantCount").value=String(Math.min(8,Math.max(1,p.players)));$("rateMode").value=p.rate===standardRate(p.players)?'standard':'custom';updateRate();if($("rateMode").value==='custom'){$("ratePerPerson").readOnly=false;$("ratePerPerson").value=p.rate;}const startOpt=[...$("bookingStart").options].find(o=>Number(o.value)===p.start);if(startOpt){$("bookingStart").value=String(p.start);const slots=await fetchSlots(p.date),map=new Map(slots.map(r=>[Number(r.start_hour),r.status]));populateEnd(map);const endOpt=[...$("bookingEnd").options].find(o=>Number(o.value)===p.end);if(endOpt)$("bookingEnd").value=String(p.end);}updateTotal();$("savePendingBtn").disabled=false;if(bad.length){res.className='parse-result error';res.innerHTML='<strong>Parsed, but there is a conflict.</strong><br>'+bad.join('<br>')+'<br><small>You can still save this as a Pending Inquiry, then agree on another time.</small>';}else{res.className='parse-result ok';res.innerHTML=`<strong>Available.</strong> ${p.name} • ${p.date} • ${hourName(p.start)}–${hourName(p.end)} • ${p.players} player(s).<br><small>The New Booking form below has been auto-filled. Review it, then use Review & Confirm Booking.</small>`;document.getElementById('quickBookingForm').scrollIntoView({behavior:'smooth',block:'start'});}};
