async function loadReports(){const {data,error}=await db.from('bookings').select('session_date,start_hour,end_hour,total_amount,amount_paid,status,participant_count');if(error)return;const rows=data||[],active=rows.filter(x=>x.status!=='cancelled'),today=new Date(),t=todayStr(),weekStart=new Date(today);weekStart.setDate(today.getDate()-((today.getDay()+6)%7));const weekEnd=new Date(weekStart);weekEnd.setDate(weekStart.getDate()+6);const ms=new Date(today.getFullYear(),today.getMonth(),1),me=new Date(today.getFullYear(),today.getMonth()+1,0);const calc=(arr,p)=>{const gross=arr.reduce((a,x)=>a+Number(x.total_amount||0),0),paid=arr.reduce((a,x)=>a+Number(x.amount_paid||0),0);$(p+'Gross').textContent=peso(gross);$(p+'Meta').textContent=`${arr.length} session(s) • ${peso(paid)} collected`;};calc(active.filter(x=>x.session_date===t),'today');calc(active.filter(x=>x.session_date>=dateStr(weekStart)&&x.session_date<=dateStr(weekEnd)),'week');const monthRows=active.filter(x=>x.session_date>=dateStr(ms)&&x.session_date<=dateStr(me));calc(monthRows,'month');calc(active,'all');$("monthHours").textContent=monthRows.reduce((a,x)=>a+(Number(x.end_hour)-Number(x.start_hour)),0);$("cancelCount").textContent=rows.filter(x=>x.status==='cancelled').length;renderCharts(active);}
function renderCharts(active){const labels=[],values=[];for(let i=13;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const ds=dateStr(d);labels.push(d.toLocaleDateString('en-PH',{month:'short',day:'numeric'}));values.push(active.filter(x=>x.session_date===ds).reduce((a,x)=>a+Number(x.total_amount||0),0));}const groups=[1,2,3,4,5].map(n=>active.filter(x=>Number(x.participant_count)===n).length);if(incomeChart)incomeChart.destroy();if(mixChart)mixChart.destroy();incomeChart=new Chart($("incomeChart"),{type:'bar',data:{labels,datasets:[{label:'Booked value',data:values,backgroundColor:'#173d2a',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}});mixChart=new Chart($("mixChart"),{type:'doughnut',data:{labels:['1 player','2 players','3 players','4 players','5 players'],datasets:[{data:groups,backgroundColor:['#173d2a','#5f813e','#d9f75c','#e5aa30','#9aa39d']}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:10,font:{size:10}}}}}});}
// Admin month calendar
const adminCalendarEl=$("adminCalendar"),adminMonthLabel=$("adminMonthLabel");let adminCalendarView=new Date();adminCalendarView.setDate(1);function adminDayState(map,date){let booked=0,unavailable=0,available=0;for(let h=8;h<24;h++){const s=map.get(`${date}|${h}`)||'available';if(s==='booked')booked++;else if(s==='unavailable')unavailable++;else available++;}if(booked===16)return{cls:'full-booked',label:'Fully booked'};if(available===0)return{cls:'full-unavailable',label:'No availability'};if(booked>0)return{cls:'partial-booked',label:`${booked} booked`};if(unavailable>0)return{cls:'partial-unavailable',label:'Limited'};return{cls:'',label:'Open'};}
async function loadAdminCalendar(){const y=adminCalendarView.getFullYear(),m=adminCalendarView.getMonth();adminMonthLabel.textContent=adminCalendarView.toLocaleDateString('en-PH',{month:'long',year:'numeric'});const last=new Date(y,m+1,0),start=`${y}-${pad(m+1)}-01`,end=`${y}-${pad(m+1)}-${pad(last.getDate())}`;const {data,error}=await db.from('schedule_slots').select('slot_date,start_hour,status').gte('slot_date',start).lte('slot_date',end);const map=new Map();if(!error)(data||[]).forEach(r=>map.set(`${r.slot_date}|${Number(r.start_hour)}`,r.status));adminCalendarEl.innerHTML='';const first=new Date(y,m,1).getDay(),today=new Date();today.setHours(0,0,0,0);for(let i=0;i<first;i++){const blank=document.createElement('span');blank.className='admin-day blank';adminCalendarEl.appendChild(blank);}for(let d=1;d<=last.getDate();d++){const dt=new Date(y,m,d),ds=`${y}-${pad(m+1)}-${pad(d)}`,state=adminDayState(map,ds),btn=document.createElement('button');btn.type='button';btn.className='admin-day';if(state.cls)btn.classList.add(state.cls);if(dt.getTime()===today.getTime())btn.classList.add('today');if(adminDate.value===ds)btn.classList.add('selected');btn.innerHTML=`<span class="day-num">${d}</span><span class="day-info">${state.label}</span>`;btn.onclick=async()=>{adminDate.value=ds;await loadDay();await loadAdminCalendar();document.querySelector('.day-section').scrollIntoView({behavior:'smooth',block:'start'});};adminCalendarEl.appendChild(btn);}}$("adminPrevMonth").onclick=()=>{adminCalendarView.setMonth(adminCalendarView.getMonth()-1);loadAdminCalendar();};$("adminNextMonth").onclick=()=>{adminCalendarView.setMonth(adminCalendarView.getMonth()+1);loadAdminCalendar();};

// Weekly schedule image generator
let weeklyImageDataUrl="",weeklyImageFilename="";
const weeklyWeekDate=$("weeklyWeekDate"),weeklyRangeLabel=$("weeklyRangeLabel"),weeklyPreviewWrap=$("weeklyPreviewWrap"),weeklyPreview=$("weeklyPreview"),downloadWeeklyBtn=$("downloadWeeklyBtn");
function localDateFromString(s){const [y,m,d]=String(s).split("-").map(Number);return new Date(y,m-1,d);}
function sundayOfWeek(input){const d=input instanceof Date?new Date(input):localDateFromString(input);d.setHours(0,0,0,0);d.setDate(d.getDate()-d.getDay());return d;}
function weeklyDates(input){const start=sundayOfWeek(input),days=[];for(let i=0;i<7;i++){const d=new Date(start);d.setDate(start.getDate()+i);days.push(d);}return days;}
function weekRangeText(input){const days=weeklyDates(input),a=days[0],b=days[6];const sameMonth=a.getMonth()===b.getMonth(),sameYear=a.getFullYear()===b.getFullYear();if(sameMonth&&sameYear)return `${a.toLocaleDateString("en-PH",{month:"long"})} ${a.getDate()}–${b.getDate()}, ${a.getFullYear()}`;if(sameYear)return `${a.toLocaleDateString("en-PH",{month:"short",day:"numeric"})} – ${b.toLocaleDateString("en-PH",{month:"short",day:"numeric"})}, ${a.getFullYear()}`;return `${a.toLocaleDateString("en-PH",{month:"short",day:"numeric",year:"numeric"})} – ${b.toLocaleDateString("en-PH",{month:"short",day:"numeric",year:"numeric"})}`;}
function refreshWeeklyRange(){if(!weeklyWeekDate)return;weeklyRangeLabel.textContent=`Sunday–Saturday • ${weekRangeText(weeklyWeekDate.value||todayStr())}`;}
if(weeklyWeekDate){weeklyWeekDate.value=todayStr();weeklyWeekDate.onchange=refreshWeeklyRange;refreshWeeklyRange();}
function roundedRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function fitText(ctx,text,maxWidth,startSize,minSize=16,weight=700){let size=startSize;while(size>minSize){ctx.font=`${weight} ${size}px Arial, sans-serif`;if(ctx.measureText(text).width<=maxWidth)break;size-=1;}return size;}
function loadCanvasImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});}
function drawImageCover(ctx,img,x,y,w,h){const s=Math.max(w/img.width,h/img.height),nw=img.width*s,nh=img.height*s;ctx.save();ctx.beginPath();ctx.roundRect(x,y,w,h,18);ctx.clip();ctx.drawImage(img,x+(w-nw)/2,y+(h-nh)/2,nw,nh);ctx.restore();}
async function fetchWeekSlots(start,end){const {data,error}=await db.from("schedule_slots").select("slot_date,start_hour,status,client_name").gte("slot_date",start).lte("slot_date",end).order("slot_date").order("start_hour");if(error)throw error;return data||[];}
async function generateWeeklyScheduleImage(){const btn=$("generateWeeklyBtn");if(!weeklyWeekDate)return;btn.disabled=true;const original=btn.textContent;btn.textContent="Generating…";try{const days=weeklyDates(weeklyWeekDate.value||todayStr()),start=dateStr(days[0]),end=dateStr(days[6]),rows=await fetchWeekSlots(start,end),map=new Map(rows.map(r=>[`${r.slot_date}|${Number(r.start_hour)}`,r]));const W=1920,H=1320,canvas=document.createElement("canvas");canvas.width=W;canvas.height=H;const ctx=canvas.getContext("2d");
ctx.fillStyle="#f8f8f6";ctx.fillRect(0,0,W,H);
// header
ctx.fillStyle="#111111";ctx.fillRect(0,0,W,178);ctx.fillStyle="#f5c400";ctx.fillRect(0,174,W,4);
try{const emblem=await loadCanvasImage("pickyla-emblem-final.png");drawImageCover(ctx,emblem,56,24,130,130);}catch(e){}
ctx.fillStyle="#ffffff";ctx.font="900 58px Arial, sans-serif";ctx.fillText("PICKYLA",218,78);ctx.fillStyle="#f5c400";ctx.font="800 24px Arial, sans-serif";ctx.fillText("WEEKLY COACHING SCHEDULE",220,118);ctx.fillStyle="#d9d9d9";ctx.font="500 22px Arial, sans-serif";ctx.fillText(weekRangeText(weeklyWeekDate.value||todayStr()),220,150);
ctx.textAlign="right";ctx.fillStyle="#ffffff";ctx.font="700 23px Arial, sans-serif";ctx.fillText("SUNDAY → SATURDAY",W-66,76);ctx.fillStyle="#bdbdbd";ctx.font="500 19px Arial, sans-serif";ctx.fillText("8:00 AM – 12:00 Midnight",W-66,111);ctx.fillStyle="#f5c400";ctx.font="700 18px Arial, sans-serif";ctx.fillText("AVAILABLE • BOOKED • BLOCKED",W-66,145);ctx.textAlign="left";
// grid geometry
const left=55,top=215,timeW=245,gridW=W-left*2,dayW=(gridW-timeW)/7,headH=82,rowH=55;
roundedRect(ctx,left,top,timeW,headH,10,"#111111");ctx.fillStyle="#ffffff";ctx.textAlign="center";ctx.font="800 24px Arial, sans-serif";ctx.fillText("TIME",left+timeW/2,top+50);
const dayNames=["SUNDAY","MONDAY","TUESDAY","WEDNESDAY","THURSDAY","FRIDAY","SATURDAY"];
for(let i=0;i<7;i++){const x=left+timeW+i*dayW;roundedRect(ctx,x+2,top,dayW-4,headH,10,"#111111");ctx.fillStyle="#ffffff";ctx.font="800 21px Arial, sans-serif";ctx.fillText(dayNames[i],x+dayW/2,top+32);ctx.fillStyle="#f5c400";ctx.font="700 16px Arial, sans-serif";ctx.fillText(days[i].toLocaleDateString("en-PH",{month:"short",day:"numeric"}).toUpperCase(),x+dayW/2,top+58);}
for(let h=8;h<24;h++){const row=h-8,y=top+headH+row*rowH;roundedRect(ctx,left,y+2,timeW,rowH-4,8,"#eeeeec");ctx.fillStyle="#202020";ctx.font="700 16px Arial, sans-serif";ctx.fillText(hourLabel(h),left+timeW/2,y+34);
for(let i=0;i<7;i++){const ds=dateStr(days[i]),x=left+timeW+i*dayW,r=map.get(`${ds}|${h}`),status=r?.status||"available";let bg="#dff4df",fg="#215b29",label="Available";if(status==="booked"){bg="#f6c5c5";fg="#8f2020";const nm=(r?.client_name||"Booked").trim();label=nm?nm.split(/\s+/)[0]:"Booked";}else if(status==="unavailable"){bg="#d9d9d9";fg="#4e4e4e";label="BLOCKED";}else{const now=new Date(),slotStart=new Date(days[i]);slotStart.setHours(h,0,0,0);if(slotStart<=now){bg="#eeeeec";fg="#8a8a86";label="PAST";}}roundedRect(ctx,x+2,y+2,dayW-4,rowH-4,8,bg);const fs=fitText(ctx,label,dayW-22,19,13,800);ctx.font=`800 ${fs}px Arial, sans-serif`;ctx.fillStyle=fg;ctx.fillText(label,x+dayW/2,y+34);}}
ctx.textAlign="left";
// legend/footer
const footerY=top+headH+16*rowH+30;ctx.fillStyle="#111111";ctx.font="800 21px Arial, sans-serif";ctx.fillText("STATUS",left,footerY+28);const legend=[['#dff4df','#215b29','AVAILABLE'],['#f6c5c5','#8f2020','BOOKED'],['#d9d9d9','#4e4e4e','BLOCKED'],['#eeeeec','#8a8a86','PAST']];legend.forEach((it,i)=>{const x=left+120+i*250;roundedRect(ctx,x,footerY,218,44,10,it[0]);ctx.fillStyle=it[1];ctx.font="800 16px Arial, sans-serif";ctx.textAlign="center";ctx.fillText(it[2],x+109,footerY+28);});ctx.textAlign="right";ctx.fillStyle="#7b7b7b";ctx.font="500 15px Arial, sans-serif";ctx.fillText("Generated from Pickyla live booking schedule",W-left,footerY+27);ctx.textAlign="left";
weeklyImageDataUrl=canvas.toDataURL("image/png",1);weeklyImageFilename=`pickyla-weekly-schedule-${start}-to-${end}.png`;weeklyPreview.src=weeklyImageDataUrl;weeklyPreviewWrap.classList.remove("hidden");weeklyPreviewWrap.scrollIntoView({behavior:"smooth",block:"nearest"});toast("Weekly schedule image ready");}catch(e){alert(`Could not generate weekly schedule image.\n${e.message}`);}finally{btn.disabled=false;btn.textContent=original;}}
if($("generateWeeklyBtn"))$("generateWeeklyBtn").onclick=generateWeeklyScheduleImage;
if(downloadWeeklyBtn)downloadWeeklyBtn.onclick=()=>{if(!weeklyImageDataUrl)return;const a=document.createElement("a");a.href=weeklyImageDataUrl;a.download=weeklyImageFilename||"pickyla-weekly-schedule.png";document.body.appendChild(a);a.click();a.remove();};

// Hour editor
function openEditor(h){const r=rowsByHour.get(h)||{status:'available'};$("editHour").value=h;$("editSlotTitle").textContent=hourLabel(h);$("editStatus").value=r.status;$("clientName").value=r.client_name||'';$("contact").value=r.contact||'';$("coachingType").value=r.coaching_type||'';$("rate").value=r.rate??'';$("notes").value=r.notes||'';toggleClientFields();editDialog.showModal();}$("editStatus").onchange=toggleClientFields;function toggleClientFields(){$("clientFields").style.opacity=$("editStatus").value==='booked'?'1':'.45';}$("closeDialog").onclick=()=>editDialog.close();$("editForm").onsubmit=async e=>{e.preventDefault();const h=Number($("editHour").value),st=$("editStatus").value,existing=rowsByHour.get(h);if(st==='available'){if(existing?.id)await db.from('schedule_slots').delete().eq('id',existing.id);}else{const p={slot_date:adminDate.value,start_hour:h,status:st,client_name:st==='booked'?$("clientName").value.trim()||null:null,contact:st==='booked'?$("contact").value.trim()||null:null,coaching_type:st==='booked'?$("coachingType").value.trim()||null:null,rate:st==='booked'?Number($("rate").value)||null:null,notes:st==='booked'?$("notes").value.trim()||null:null,booking_id:existing?.booking_id||null};const {error}=await db.from('schedule_slots').upsert(p,{onConflict:'slot_date,start_hour'});if(error)return alert(error.message);}editDialog.close();toast('Hour updated');await Promise.all([loadDay(),loadBookingAvailability(),loadAdminCalendar()]);};$("deleteBtn").onclick=async()=>{const h=Number($("editHour").value),existing=rowsByHour.get(h);if(existing?.id)await db.from('schedule_slots').delete().eq('id',existing.id);editDialog.close();toast('Hour reset');await Promise.all([loadDay(),loadBookingAvailability(),loadAdminCalendar()]);};
