// ===== v16 payment ledger, collection alerts, accurate reports =====
let paymentBookingContext=null,lastDetailedReport={rows:[],headers:[],title:"Pickyla Report",summary:[]};
function bookingEndMoment(b){const [y,m,d]=String(b.session_date).split("-").map(Number);if(Number(b.end_hour)===24)return new Date(y,m-1,d+1,0,0,0);return new Date(y,m-1,d,Number(b.end_hour),0,0);}
function paymentState(b){const total=Number(b.total_amount||0),paid=Number(b.amount_paid||0),balance=Math.max(0,total-paid);return{total,paid,balance,status:paid<=0?"none":paid+0.0001>=total?"full":"partial"};}

async function authRefresh(){
  const {data:{session}}=await db.auth.getSession();
  if(session){loginView.classList.add("hidden");adminView.classList.remove("hidden");const t=todayStr();adminDate.value||=t;$("bookingDate").value||=t;$("blockFromDate").value||=t;$("blockToDate").value||=t;adminCalendarView=new Date();adminCalendarView.setDate(1);initDetailedReportDates();await Promise.all([loadDay(),loadBookingAvailability(),loadReports(),loadAdminCalendar(),loadInquiries(),loadCollectionAlerts()]);}
  else{adminView.classList.add("hidden");loginView.classList.remove("hidden");}
}

function renderBookingGroups(){
  bookingGroups.innerHTML="";if(!bookingsForDay.length){bookingGroups.innerHTML='<div class="empty">No grouped bookings on this date.</div>';return;}
  bookingsForDay.forEach(b=>{const p=paymentState(b),card=document.createElement("article");card.className="booking-card";const badge=p.status==="full"?"Paid":p.status==="partial"?"Partial":"Unpaid";card.innerHTML=`<div class="booking-card-top"><div><h4>${b.client_name}</h4><div class="meta">${hourName(b.start_hour)}–${hourName(b.end_hour)} • ${b.participant_count} player(s) • ${b.coaching_type||""}<br>${b.rate_mode==="custom"?"Custom":"Standard"} rate: ${peso(b.rate_per_person)}/person/hr${b.contact?` • ${b.contact}`:""}</div></div><div class="money">${peso(p.total)}<small>${badge} • Collected ${peso(p.paid)} • Balance ${peso(p.balance)}</small></div></div><div class="booking-actions"><button class="pay-btn" data-act="pay">Record Payment</button><button class="confirm-card-btn" data-act="card">Confirmation Card</button><button class="cancel-btn" data-act="cancel">Cancel Whole Booking</button></div>`;card.querySelector('[data-act="pay"]').onclick=()=>updatePayment(b);const cc=card.querySelector('[data-act="card"]');if(cc)cc.onclick=()=>openConfirmationCard(b);card.querySelector('[data-act="cancel"]').onclick=()=>cancelBooking(b);bookingGroups.appendChild(card);});
}

function updatePayment(b){
  const p=paymentState(b);if(p.balance<=0)return alert("This booking is already fully collected.");paymentBookingContext=b;$("paymentBookingId").value=b.id;$("paymentAmount").value=p.balance.toFixed(2);$("paymentAmount").max=p.balance.toFixed(2);$("paymentDate").value=todayStr();$("paymentMethod").value="Cash";$("paymentNote").value="";$("paymentBookingInfo").innerHTML=`<strong>${b.client_name}</strong> • ${b.session_date} • ${hourName(Number(b.start_hour))}–${hourName(Number(b.end_hour))}<br>Booking ${peso(p.total)} • Collected ${peso(p.paid)} • <strong>Balance ${peso(p.balance)}</strong>`;$("paymentDialog").showModal();
}
if($("closePaymentDialog"))$("closePaymentDialog").onclick=()=>$("paymentDialog").close();if($("cancelPaymentDialog"))$("cancelPaymentDialog").onclick=()=>$("paymentDialog").close();
if($("paymentForm"))$("paymentForm").onsubmit=async e=>{e.preventDefault();if(!paymentBookingContext)return;const state=paymentState(paymentBookingContext),amount=Number($("paymentAmount").value);if(!amount||amount<=0)return alert("Enter a valid payment amount.");if(amount>state.balance+0.001)return alert(`Payment is higher than the outstanding balance (${peso(state.balance)}).`);const row={booking_id:paymentBookingContext.id,amount,paid_at:$("paymentDate").value,payment_method:$("paymentMethod").value,note:$("paymentNote").value.trim()||null,source:"manual"};const {error}=await db.from("booking_payments").insert(row);if(error)return alert(`Payment could not be saved. Make sure the v16 Supabase migration has been run.\n\n${error.message}`);$("paymentDialog").close();toast("Payment recorded");await Promise.all([loadDay(),loadReports(),loadCollectionAlerts()]);};

async function loadCollectionAlerts(){
  const section=$("collectionAlertSection"),list=$("collectionAlertList");if(!section||!list)return;const {data,error}=await db.from("bookings").select("*").neq("status","cancelled").lte("session_date",todayStr()).order("session_date",{ascending:false});if(error){$("collectionDueCount").textContent="!";return;}const now=new Date(),due=(data||[]).filter(b=>bookingEndMoment(b)<now&&paymentState(b).balance>0);$("collectionDueCount").textContent=due.length;if(!due.length){section.classList.add("hidden");list.innerHTML="";return;}section.classList.remove("hidden");list.innerHTML="";due.forEach(b=>{const p=paymentState(b),el=document.createElement("article");el.className="collection-alert-item";el.innerHTML=`<div><h4>${b.client_name}</h4><p>${b.session_date} • ${hourName(Number(b.start_hour))}–${hourName(Number(b.end_hour))}<br>${p.status==="partial"?`Partial collection: ${peso(p.paid)}`:"No collection recorded yet."}</p></div><div class="collection-alert-balance"><span>Outstanding</span><strong>${peso(p.balance)}</strong><button type="button">Record Payment</button></div>`;el.querySelector("button").onclick=()=>updatePayment(b);list.appendChild(el);});
}

// Booking save now writes initial collection to the payment ledger.
$("quickBookingForm").onsubmit=async e=>{e.preventDefault();const d=$("bookingDate").value,s=Number($("bookingStart").value),en=Number($("bookingEnd").value),n=Number($("participantCount").value),r=Number($("ratePerPerson").value),initial=Number($("amountPaid").value||0),total=(en-s)*n*r;if(!d||!s||!en||en<=s)return alert("Choose a valid date/time range.");if(initial>total)return alert("Initial payment cannot be higher than the booking total.");const bad=await conflictsFor(d,s,en);if(bad.length)return alert("Schedule conflict:\n"+bad.join("\n"));const client=$("bookingClient").value.trim();const summary=`Confirm booking?\n\n${client}\n${d} • ${hourName(s)}–${hourName(en)}\n${n} player(s) • ${peso(r)}/person/hr\nTotal: ${peso(total)}${initial?`\nInitial payment: ${peso(initial)}`:""}`;if(!confirm(summary))return;const book={session_date:d,start_hour:s,end_hour:en,client_name:client,contact:$("bookingContact").value.trim()||null,participant_count:n,coaching_type:coachingType(n),rate_mode:$("rateMode").value,rate_per_person:r,total_amount:total,amount_paid:0,notes:$("bookingNotes").value.trim()||null,status:"confirmed"};const {data:b,error:e1}=await db.from("bookings").insert(book).select().single();if(e1)return alert(e1.message);const slotRows=[];for(let h=s;h<en;h++)slotRows.push({slot_date:d,start_hour:h,status:"booked",client_name:book.client_name,contact:book.contact,coaching_type:book.coaching_type,rate:r,notes:book.notes,booking_id:b.id});const {error:e2}=await db.from("schedule_slots").insert(slotRows);if(e2){await db.from("bookings").delete().eq("id",b.id);return alert(e2.message);}if(initial>0){const {error:pe}=await db.from("booking_payments").insert({booking_id:b.id,amount:initial,paid_at:todayStr(),payment_method:"Cash",note:"Initial payment recorded when booking was created",source:"booking_create"});if(pe){await db.from("schedule_slots").delete().eq("booking_id",b.id);await db.from("bookings").delete().eq("id",b.id);return alert(`Booking was not saved because the payment ledger is not ready. Run the v16 migration first.\n\n${pe.message}`);}}toast("Booking saved");adminDate.value=d;$("bookingClient").value="";$("bookingContact").value="";$("bookingNotes").value="";$("amountPaid").value="0";await Promise.all([loadDay(),loadBookingAvailability(),loadReports(),loadAdminCalendar(),loadInquiries(),loadCollectionAlerts()]);};

async function loadReports(){const {data,error}=await db.from("bookings").select("session_date,start_hour,end_hour,total_amount,amount_paid,status,participant_count");if(error)return;const rows=data||[],active=rows.filter(x=>x.status!=="cancelled"),today=new Date(),t=todayStr(),weekStart=new Date(today);weekStart.setDate(today.getDate()-today.getDay());const weekEnd=new Date(weekStart);weekEnd.setDate(weekStart.getDate()+6);const ms=new Date(today.getFullYear(),today.getMonth(),1),me=new Date(today.getFullYear(),today.getMonth()+1,0);const calc=(arr,p)=>{const gross=arr.reduce((a,x)=>a+Number(x.total_amount||0),0),paid=arr.reduce((a,x)=>a+Number(x.amount_paid||0),0);$(p+"Gross").textContent=peso(gross);$(p+"Meta").textContent=`${arr.length} session(s) • ${peso(paid)} collected`;};calc(active.filter(x=>x.session_date===t),"today");calc(active.filter(x=>x.session_date>=dateStr(weekStart)&&x.session_date<=dateStr(weekEnd)),"week");const monthRows=active.filter(x=>x.session_date>=dateStr(ms)&&x.session_date<=dateStr(me));calc(monthRows,"month");calc(active,"all");$("monthHours").textContent=monthRows.reduce((a,x)=>a+(Number(x.end_hour)-Number(x.start_hour)),0);$("cancelCount").textContent=rows.filter(x=>x.status==="cancelled").length;renderCharts(active);}
function renderCharts(active){const labels=[],values=[];for(let i=13;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const ds=dateStr(d);labels.push(d.toLocaleDateString("en-PH",{month:"short",day:"numeric"}));values.push(active.filter(x=>x.session_date===ds).reduce((a,x)=>a+Number(x.total_amount||0),0));}const groups=[1,2,3,4,5].map(n=>active.filter(x=>Number(x.participant_count)===n).length);if(incomeChart)incomeChart.destroy();if(mixChart)mixChart.destroy();incomeChart=new Chart($("incomeChart"),{type:"bar",data:{labels,datasets:[{label:"Booked value",data:values,backgroundColor:"#f5c400",borderColor:"#111111",borderWidth:1,borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}});mixChart=new Chart($("mixChart"),{type:"doughnut",data:{labels:["1 player","2 players","3 players","4 players","5 players"],datasets:[{data:groups,backgroundColor:["#111111","#f5c400","#d8a800","#9d9d9d","#e8dfbd"]}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom",labels:{boxWidth:10,font:{size:10}}}}}});}

function initDetailedReportDates(){if(!$("reportFrom"))return;const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),1);$("reportFrom").value||=dateStr(start);$("reportTo").value||=todayStr();}
if($("detailedReportType"))$("detailedReportType").onchange=()=>{$("reportStatusWrap").classList.toggle("hidden",$("detailedReportType").value==="cash");};
function filterBookingRows(rows,filter){return rows.filter(b=>{if(filter==="cancelled")return b.status==="cancelled";if(b.status==="cancelled")return false;const s=paymentState(b).status;if(filter==="all")return true;if(filter==="full")return s==="full";if(filter==="partial")return s==="partial";if(filter==="none")return s==="none";if(filter==="outstanding")return s!=="full";return true;});}
