// ===== v17-A coaching platform foundation =====
let v17Clients=[],v17Programs=[],v17SelectedClient=null,v17BookingProgramContext=null,v17ProgramPaymentContext=null,v17EditingProgramId=null;
const v17FocusLabels={beginner:"Beginner","serve-return":"Serve & Return",footwork:"Footwork",dinking:"Dinking & Kitchen",consistency:"Consistency",strategy:"Strategy",tournament:"Tournament Prep"};
const v17ScoreFields=[
  ["scoreServe","serve","Serve"],["scoreReturn","return_score","Return"],["scoreForehand","forehand","Forehand"],["scoreBackhand","backhand","Backhand"],["scoreDinking","dinking","Dinking"],
  ["scoreFootwork","footwork","Footwork"],["scorePositioning","positioning","Positioning"],["scoreConsistency","consistency","Consistency"],["scoreStrategy","strategy","Strategy"],["scoreConfidence","confidence","Confidence"]
];
function v17ContactKey(v){const x=String(v||"").trim().toLowerCase().replace(/\s+/g," ");return x||null;}
function v17SessionLabel(v){return({scheduled:"Scheduled",completed:"Completed",client_cancelled:"Client Cancelled",coach_cancelled:"Coach Cancelled",no_show:"No Show",cancelled:"Cancelled"})[v]||v||"Scheduled";}
function v17StatusClass(v){return `status-${String(v||"scheduled").replace(/[^a-z_]/g,"")}`;}
function v17ScoreText(v){return({1:"Needs Foundation",2:"Developing",3:"Functional",4:"Consistent",5:"Strong"})[Number(v)]||"Not rated";}
function v17EndMoment(b){return bookingEndMoment(b);}
function v17IsCancelled(b){return b.status==="cancelled"||["client_cancelled","coach_cancelled","cancelled"].includes(b.session_status);}
function v17Escape(v){return escapeHtml(v);}

async function v17EnsureClient(name,contact){
  const key=v17ContactKey(contact);if(!key)return null;
  const {data:found,error:fe}=await db.from("clients").select("*").eq("contact_key",key).maybeSingle();
  if(fe)throw fe;
  if(found){
    const updates={};if(name&&String(name).trim()&&found.full_name!==String(name).trim())updates.full_name=String(name).trim();if(contact&&found.contact!==String(contact).trim())updates.contact=String(contact).trim();
    if(Object.keys(updates).length)await db.from("clients").update(updates).eq("id",found.id);
    return found.id;
  }
  const {data,error}=await db.from("clients").insert({full_name:String(name||"").trim(),contact:String(contact||"").trim(),contact_key:key}).select().single();
  if(error)throw error;return data.id;
}

async function loadV17Clients(){
  const list=$("clientList");if(!list)return;
  const {data,error}=await db.from("clients").select("*").eq("is_active",true).order("full_name");
  if(error){list.innerHTML=`<div class="empty">${v17Escape(error.message)} — run the v17-A migration first.</div>`;return;}
  v17Clients=data||[];renderV17Clients();
}
function renderV17Clients(){
  const list=$("clientList");if(!list)return;const q=String($("clientSearch")?.value||"").trim().toLowerCase();const rows=v17Clients.filter(c=>!q||String(c.full_name||"").toLowerCase().includes(q)||String(c.contact||"").toLowerCase().includes(q));
  $("clientCountLabel").textContent=`${rows.length} client${rows.length===1?"":"s"}`;list.innerHTML="";
  if(!rows.length){list.innerHTML='<div class="empty">No matching client profiles.</div>';return;}
  rows.forEach(c=>{const el=document.createElement("article");el.className="client-card";el.innerHTML=`<div class="client-card-top"><div><h4>${v17Escape(c.full_name)}</h4><p>${v17Escape(c.contact||"No contact saved")}${c.notes?`<br>${v17Escape(c.notes)}`:""}</p></div><button type="button">Open Profile</button></div>`;el.querySelector("button").onclick=()=>openV17Client(c.id);list.appendChild(el);});
}
if($("clientSearch"))$("clientSearch").oninput=renderV17Clients;

async function loadV17Programs(){
  const list=$("programList");if(!list)return;
  const {data,error}=await db.from("coaching_programs").select("*").order("is_active",{ascending:false}).order("created_at",{ascending:false});
  if(error){list.innerHTML=`<div class="empty">${v17Escape(error.message)} — run the v17-A migration first.</div>`;return;}
  v17Programs=data||[];renderV17Programs();refreshEnrollProgramOptions();
}
function renderV17Programs(){
  const list=$("programList");if(!list)return;list.innerHTML="";if(!v17Programs.length){list.innerHTML='<div class="empty">No coaching programs yet. Create your first structured package.</div>';return;}
  v17Programs.forEach(p=>{const el=document.createElement("article");el.className="program-card";const focus=(p.focus_areas||[]).map(x=>`<span>${v17Escape(v17FocusLabels[x]||x)}</span>`).join("");el.innerHTML=`<div class="program-card-top"><div><h4>${v17Escape(p.name)}</h4><p>${v17Escape(p.overall_goal||p.description||"No overall goal yet.")}</p></div><div class="program-price">${peso(p.fixed_price)}</div></div><div class="program-meta"><span>${p.session_count} sessions</span><span>${Number(p.session_duration_hours)} hr/session</span><span>${p.is_active?"ACTIVE":"INACTIVE"}</span></div>${focus?`<div class="program-focus-chips">${focus}</div>`:""}<div class="program-actions"><button type="button" data-goals>View Goals</button><button type="button" data-edit>Edit</button><button type="button" data-toggle>${p.is_active?"Deactivate":"Activate"}</button></div>`;
    el.querySelector("[data-goals]").onclick=()=>viewV17ProgramGoals(p);el.querySelector("[data-edit]").onclick=()=>openV17ProgramDialog(p);el.querySelector("[data-toggle]").onclick=async()=>{await db.from("coaching_programs").update({is_active:!p.is_active}).eq("id",p.id);toast(`Program ${p.is_active?"deactivated":"activated"}`);loadV17Programs();};list.appendChild(el);});
}
async function viewV17ProgramGoals(p){const {data,error}=await db.from("coaching_program_sessions").select("*").eq("program_id",p.id).order("session_number");if(error)return alert(error.message);const text=(data||[]).map(x=>`Session ${x.session_number}: ${x.title}\n${x.goal||""}`).join("\n\n")||"No session goals saved.";alert(`${p.name}\n\nOverall goal:\n${p.overall_goal||"—"}\n\n${text}`);}

function buildV17ProgramGoalRows(){
  const wrap=$("programGoalRows");if(!wrap)return;const count=Math.max(1,Math.min(50,Number($("programSessionCount").value||10)));const existing=[...wrap.querySelectorAll(".program-goal-row")].map(r=>({title:r.querySelector("input")?.value||"",goal:r.querySelector("textarea")?.value||""}));wrap.innerHTML="";
  for(let i=1;i<=count;i++){const row=document.createElement("div");row.className="program-goal-row";row.innerHTML=`<div class="goal-num">${i}</div><input type="text" maxlength="140" value="${v17Escape(existing[i-1]?.title||`Session ${i}`)}" placeholder="Session title"><textarea rows="2" placeholder="Goal for session ${i}">${v17Escape(existing[i-1]?.goal||"")}</textarea>`;wrap.appendChild(row);}
}
