// v17-A booking save: auto-link by contact, and support fixed-price program sessions without double charging.
$("quickBookingForm").onsubmit=async e=>{
  e.preventDefault();const d=$("bookingDate").value,s=Number($("bookingStart").value),en=Number($("bookingEnd").value),n=Number($("participantCount").value);if(!d||!s||!en||en<=s)return alert("Choose a valid date/time range.");const bad=await conflictsFor(d,s,en);if(bad.length)return alert("Schedule conflict:\n"+bad.join("\n"));
  const ctx=v17BookingProgramContext,clientName=(ctx?.client?.full_name||$("bookingClient").value.trim()),contact=(ctx?.client?.contact||$("bookingContact").value.trim()||null);let r=Number($("ratePerPerson").value||0),initial=Number($("amountPaid").value||0),total=(en-s)*n*r,clientId=ctx?.client?.id||null;if(ctx){r=0;initial=0;total=0;}else if(initial>total)return alert("Initial payment cannot be higher than the booking total.");
  try{if(!clientId&&contact)clientId=await v17EnsureClient(clientName,contact);}catch(err){return alert(`Could not link the client profile.\n\n${err.message}`);}
  const summary=`Confirm booking?\n\n${clientName}\n${d} • ${hourName(s)}–${hourName(en)}\n${n} player(s)${ctx?`\n${ctx.program.name} • Session ${ctx.sessionNumber}/${ctx.program.session_count}\nFixed package — no separate hourly charge`:` • ${peso(r)}/person/hr\nTotal: ${peso(total)}${initial?`\nInitial payment: ${peso(initial)}`:""}`}`;if(!confirm(summary))return;
  const book={session_date:d,start_hour:s,end_hour:en,client_name:clientName,contact,participant_count:n,coaching_type:ctx?ctx.program.name:coachingType(n),rate_mode:ctx?"custom":$("rateMode").value,rate_per_person:r,total_amount:total,amount_paid:0,notes:$("bookingNotes").value.trim()||null,status:"confirmed",client_id:clientId,client_program_id:ctx?.enrollment?.id||null,program_session_number:ctx?.sessionNumber||null,session_status:"scheduled"};const {data:b,error:e1}=await db.from("bookings").insert(book).select().single();if(e1)return alert(`Booking could not be saved. Run the v17-A migration first.\n\n${e1.message}`);
  const slotRows=[];for(let h=s;h<en;h++)slotRows.push({slot_date:d,start_hour:h,status:"booked",client_name:book.client_name,contact:book.contact,coaching_type:book.coaching_type,rate:r,notes:book.notes,booking_id:b.id});const {error:e2}=await db.from("schedule_slots").insert(slotRows);if(e2){await db.from("bookings").delete().eq("id",b.id);return alert(e2.message);}if(initial>0){const {error:payErr}=await db.from("booking_payments").insert({booking_id:b.id,amount:initial,paid_at:todayStr(),payment_method:"Cash",note:"Initial payment recorded when booking was created",source:"booking_create"});if(payErr){await db.from("schedule_slots").delete().eq("booking_id",b.id);await db.from("bookings").delete().eq("id",b.id);return alert(payErr.message);}}
  toast(ctx?"Program session scheduled":"Booking saved");adminDate.value=d;$("bookingClient").value="";$("bookingContact").value="";$("bookingNotes").value="";$("amountPaid").value="0";v17BookingProgramContext=null;$("rateMode").value="standard";updateRate();await Promise.all([loadDay(),loadBookingAvailability(),loadReports(),loadAdminCalendar(),loadInquiries(),loadCollectionAlerts(),loadTodayCommandCenter(),loadPaymentDashboard(),loadV17Clients()]);if(clientId&&v17SelectedClient?.id===clientId)await openV17Client(clientId);
};

