function v17eOpenTestimonial(t=null){v17eEditingTestimonialId=t?.id||null;$("testimonialForm").reset();$("testimonialDialogTitle").textContent=t?"Review client story":"Add client story";$("testimonialDialogMeta").textContent=t?.source==="public"?"Submitted from the public site. You can make minor wording adjustments before approval.":"Admin-created testimonial.";$("testimonialName").value=t?.display_name||"";$("testimonialLevel").value=t?.player_level||"";$("testimonialQuote").value=t?.quote||"";$("testimonialReviewStatus").value=t? v17eTestimonialStatus(t):"approved";$("testimonialPublished").checked=t?!!t.is_published:true;$("testimonialSaveBtn").textContent=t?"Save Changes":"Save Testimonial";$("testimonialDialog").showModal();}
async function loadV17BTestimonials(){const list=$("testimonialAdminList");if(!list)return;const {data,error}=await db.from("testimonials").select("*").order("created_at",{ascending:false});if(error){list.innerHTML=`<div class="empty">${v17Escape(error.message)} — run the v17-E migration first.</div>`;return;}v17bTestimonials=(data||[]).sort((a,b)=>{const w={pending:0,approved:1,rejected:2};const d=(w[v17eTestimonialStatus(a)]??9)-(w[v17eTestimonialStatus(b)]??9);return d||new Date(b.created_at)-new Date(a.created_at);});list.innerHTML="";if(!v17bTestimonials.length){list.innerHTML='<div class="empty">No testimonials yet. Public submissions will appear here for review.</div>';return;}v17bTestimonials.forEach(t=>{const status=v17eTestimonialStatus(t),el=document.createElement("article");el.className=`testimonial-admin-card ${status}`;const source=t.source==="public"?"Public submission":"Admin";el.innerHTML=`<div class="testimonial-status-row"><span class="testimonial-status-badge ${status}">${status}</span><span class="testimonial-source-badge">${source}${t.is_published?" • Published":" • Private"}</span></div><blockquote>“${v17Escape(t.quote)}”</blockquote><div class="testimonial-admin-meta"><div><strong>${v17Escape(t.display_name)}</strong><small> • ${v17Escape(t.player_level||"Client")}</small></div><div class="testimonial-admin-actions"><button class="edit" type="button">Review / Edit</button>${status==="pending"?'<button class="approve" type="button">Approve & Publish</button><button class="reject" type="button">Reject</button>':`<button class="publish" type="button">${t.is_published?"Hide":"Publish"}</button>`}<button class="delete" type="button">Delete</button></div></div>`;const edit=el.querySelector(".edit"),approve=el.querySelector(".approve"),reject=el.querySelector(".reject"),toggle=el.querySelector(".publish"),del=el.querySelector(".delete");edit.onclick=()=>v17eOpenTestimonial(t);if(approve)approve.onclick=async()=>{const {error}=await db.from("testimonials").update({review_status:"approved",is_published:true}).eq("id",t.id);if(error)return alert(error.message);toast("Testimonial approved & published");loadV17BTestimonials();};if(reject)reject.onclick=async()=>{const {error}=await db.from("testimonials").update({review_status:"rejected",is_published:false}).eq("id",t.id);if(error)return alert(error.message);toast("Testimonial rejected");loadV17BTestimonials();};if(toggle)toggle.onclick=async()=>{const publish=!t.is_published;const {error}=await db.from("testimonials").update({is_published:publish,review_status:publish?"approved":status}).eq("id",t.id);if(error)return alert(error.message);toast(publish?"Testimonial published":"Testimonial hidden");loadV17BTestimonials();};del.onclick=async()=>{if(!confirm("Delete this testimonial?"))return;await db.from("testimonials").delete().eq("id",t.id);loadV17BTestimonials();};list.appendChild(el);});}
if($("addTestimonialBtn"))$("addTestimonialBtn").onclick=()=>v17eOpenTestimonial();if($("closeTestimonialDialog"))$("closeTestimonialDialog").onclick=()=>$("testimonialDialog").close();if($("cancelTestimonialDialog"))$("cancelTestimonialDialog").onclick=()=>$("testimonialDialog").close();if($("testimonialPublished"))$("testimonialPublished").onchange=()=>{if($("testimonialPublished").checked)$("testimonialReviewStatus").value="approved";};if($("testimonialReviewStatus"))$("testimonialReviewStatus").onchange=()=>{if($("testimonialReviewStatus").value!=="approved")$("testimonialPublished").checked=false;};if($("testimonialForm"))$("testimonialForm").onsubmit=async e=>{e.preventDefault();let review_status=$("testimonialReviewStatus").value,is_published=$("testimonialPublished").checked;if(is_published)review_status="approved";if(review_status!=="approved")is_published=false;const row={display_name:$("testimonialName").value.trim(),player_level:$("testimonialLevel").value.trim()||null,quote:$("testimonialQuote").value.trim(),review_status,is_published,source:v17eEditingTestimonialId?(v17bTestimonials.find(x=>x.id===v17eEditingTestimonialId)?.source||"admin"):"admin"};const q=v17eEditingTestimonialId?db.from("testimonials").update(row).eq("id",v17eEditingTestimonialId):db.from("testimonials").insert(row);const {error}=await q;if(error)return alert(error.message);$("testimonialDialog").close();toast(v17eEditingTestimonialId?"Testimonial updated":"Testimonial saved");v17eEditingTestimonialId=null;loadV17BTestimonials();};
function initPublicQr(){const box=$("publicQrCode");if(!box||typeof QRCode==="undefined")return;box.innerHTML="";new QRCode(box,{text:"https://pickyla-coaching.xbalanced.net/",width:150,height:150,colorDark:"#111111",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.H});}
if($("downloadPublicQr"))$("downloadPublicQr").onclick=()=>{const box=$("publicQrCode"),src=box?.querySelector("canvas")?.toDataURL("image/png")||box?.querySelector("img")?.src;if(!src)return alert("QR is still loading. Try again.");const a=document.createElement("a");a.href=src;a.download="pickyla-public-site-qr.png";a.click();};
async function canvasImage(src){return new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=src;});}
function wrapCanvasText(ctx,text,x,y,maxWidth,lineHeight,maxLines=4){const words=String(text||"").split(/\s+/);let line="",lines=[];for(const word of words){const test=line?line+" "+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word;}else line=test;}if(line)lines.push(line);lines=lines.slice(0,maxLines);lines.forEach((l,i)=>ctx.fillText(l,x,y+i*lineHeight));return y+lines.length*lineHeight;}
async function generateConfirmationCard(b){const c=document.createElement("canvas");c.width=1080;c.height=1350;const x=c.getContext("2d");x.fillStyle="#111";x.fillRect(0,0,c.width,c.height);x.fillStyle="#f5c400";x.fillRect(0,0,c.width,18);x.fillRect(0,1332,c.width,18);try{const logo=await canvasImage("pickyla-emblem-final.png");x.drawImage(logo,70,70,150,150);}catch{}x.fillStyle="#f5c400";x.font="800 28px Manrope, Arial";x.fillText("PICKYLA",250,120);x.fillStyle="#fff";x.font="800 54px Manrope, Arial";x.fillText("BOOKING CONFIRMED",70,305);x.fillStyle="#aaa";x.font="600 24px Arial";x.fillText("Pickleball Coaching • Santiago City, Isabela",70,350);x.fillStyle="#222";roundRectCanvas(x,70,405,940,750,34);x.fill();const rows=[["CLIENT",b.client_name],["DATE",new Date(`${b.session_date}T00:00:00`).toLocaleDateString("en-PH",{weekday:"long",month:"long",day:"numeric",year:"numeric"})],["TIME",`${hourName(Number(b.start_hour))} – ${hourName(Number(b.end_hour))}`],["PLAYERS",`${b.participant_count||1} player${Number(b.participant_count)===1?"":"s"}`],["COACHING",b.coaching_type||"Pickleball Coaching"]];if(b.client_program_id)rows.push(["PROGRAM SESSION",`Session ${b.program_session_number||"—"}`]);let yy=485;for(const [lab,val] of rows){x.fillStyle="#f5c400";x.font="800 19px Arial";x.fillText(lab,120,yy);x.fillStyle="#fff";x.font="700 29px Manrope, Arial";yy=wrapCanvasText(x,val,120,yy+42,820,38,2)+38;}const p=paymentState(b);x.fillStyle="#f5c400";x.font="800 19px Arial";x.fillText("PAYMENT",120,1070);x.fillStyle="#fff";x.font="700 28px Manrope, Arial";x.fillText(b.client_program_id?"Program package payment tracked separately":(p.balance<=0?"Fully Collected":`${peso(p.balance)} outstanding`),120,1112);x.fillStyle="#aaa";x.font="500 20px Arial";x.fillText("Please message Pickyla if you need to change your schedule.",70,1245);return c.toDataURL("image/png");}
function roundRectCanvas(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}
async function openConfirmationCard(b){try{confirmationCardDataUrl=await generateConfirmationCard(b);$("confirmationCardPreview").src=confirmationCardDataUrl;$("confirmationCardDialog").showModal();}catch(e){alert("Could not generate the confirmation card: "+e.message);}}
if($("closeConfirmationCard"))$("closeConfirmationCard").onclick=()=>$("confirmationCardDialog").close();if($("cancelConfirmationCard"))$("cancelConfirmationCard").onclick=()=>$("confirmationCardDialog").close();if($("downloadConfirmationCard"))$("downloadConfirmationCard").onclick=()=>{if(!confirmationCardDataUrl)return;const a=document.createElement("a");a.href=confirmationCardDataUrl;a.download=`pickyla-booking-confirmation-${todayStr()}.png`;a.click();};

