// ===== v17-D structured participants, canonical client identity, participant history =====
let v17dLoadedInquiryId=null,v17dLoadedInquiryParticipants=[];
function v17dClean(v){return String(v||"").trim().replace(/\s+/g," ");}
function v17dTitle(v){return v17dClean(v).split(" ").map(w=>w.split(/([-'])/).map(p=>/[-']/.test(p)?p:(p?p.charAt(0).toUpperCase()+p.slice(1).toLowerCase():p)).join("")).join(" ");}
function v17dNameKey(first,last){return v17dClean(`${first||""} ${last||""}`).toLowerCase();}
function v17dFull(p){return v17dClean(`${p.first_name||""} ${p.last_name||""}`);}
function v17dSplitLegacyName(full){const parts=v17dClean(full).split(" ").filter(Boolean);if(parts.length<=1)return{first_name:parts[0]||"",last_name:""};return{first_name:parts.slice(0,-1).join(" "),last_name:parts.at(-1)};}
function v17dCurrentAdminParticipants(){const list=$("adminParticipantList");if(!list)return[];return[...list.querySelectorAll(".admin-participant-row")].map(r=>({first_name:v17dTitle(r.querySelector("[data-first]")?.value||""),last_name:v17dTitle(r.querySelector("[data-last]")?.value||""),contact:v17dClean(r.querySelector("[data-contact]")?.value||"")||null}));}
function v17dRenderAdminParticipants(count=1,seed=null){const list=$("adminParticipantList");if(!list)return;count=Math.min(8,Math.max(1,Number(count)||1));const prev=seed||v17dCurrentAdminParticipants();list.innerHTML="";for(let i=0;i<count;i++){const p=prev[i]||{},row=document.createElement("div");row.className="admin-participant-row";row.innerHTML=`<div class="admin-player-num">P${i+1}</div><label>First name<input data-first maxlength="60" required></label><label>Last name<input data-last maxlength="80" required></label><label>Contact <small>(optional)</small><input data-contact maxlength="120"></label>`;row.querySelector("[data-first]").value=p.first_name||"";row.querySelector("[data-last]").value=p.last_name||"";row.querySelector("[data-contact]").value=p.contact||"";row.querySelectorAll("input").forEach(inp=>{inp.addEventListener("blur",()=>{if(inp.hasAttribute("data-first")||inp.hasAttribute("data-last"))inp.value=v17dTitle(inp.value);v17dSyncPrimaryHidden();});inp.addEventListener("input",v17dSyncPrimaryHidden);});list.appendChild(row);}if($("adminParticipantCountLabel"))$("adminParticipantCountLabel").textContent=`${count} player${count===1?"":"s"}`;v17dSyncPrimaryHidden();}
function v17dSyncPrimaryHidden(){const p=v17dCurrentAdminParticipants()[0];if($("bookingClient"))$("bookingClient").value=p?v17dFull(p):"";if($("bookingContact"))$("bookingContact").value=p?.contact||"";}
function v17dSetBookingParticipants(rows,count=null){const normalized=(rows||[]).map(p=>({first_name:p.first_name||v17dSplitLegacyName(p.full_name||"").first_name,last_name:p.last_name||v17dSplitLegacyName(p.full_name||"").last_name,contact:p.contact||null}));const n=count||normalized.length||1;$("participantCount").value=String(Math.min(8,Math.max(1,n)));v17dRenderAdminParticipants(n,normalized);updateRate();}
if($("participantCount"))$("participantCount").onchange=()=>{const n=Number($("participantCount").value);v17dRenderAdminParticipants(n);updateRate();};
v17dRenderAdminParticipants(Number($("participantCount")?.value||1));

async function v17dResolveClient(p,allowNamePrompt=true){const first=v17dTitle(p.first_name),last=v17dTitle(p.last_name),full=v17dFull({first_name:first,last_name:last}),name_key=v17dNameKey(first,last),contact=v17dClean(p.contact)||null,contact_key=v17ContactKey(contact);if(!first||!last)throw new Error("Every player needs a first name and last name.");
  if(contact_key){const {data,error}=await db.from("clients").select("*").eq("contact_key",contact_key).eq("name_key",name_key);if(error)throw error;if((data||[]).length===1){const c=data[0],updates={};if(!c.first_name)updates.first_name=first;if(!c.last_name)updates.last_name=last;if(c.contact!==contact)updates.contact=contact;if(!c.name_key)updates.name_key=name_key;if(Object.keys(updates).length)await db.from("clients").update(updates).eq("id",c.id);return{...c,...updates};}}
  const {data:matches,error:me}=await db.from("clients").select("*").eq("name_key",name_key).eq("is_active",true);if(me)throw me;if(allowNamePrompt&&(matches||[]).length===1){const m=matches[0];if(confirm(`Possible repeat client found:\n\n${m.full_name}${m.contact?`\n${m.contact}`:""}\n\nLink this player to the existing client profile?`))return m;}
  const {data,error}=await db.from("clients").insert({first_name:first,last_name:last,full_name:full,name_key,contact,contact_key}).select().single();if(error){if(error.code==="23505"){const {data:again}=await db.from("clients").select("*").eq("name_key",name_key).eq("contact_key",contact_key).maybeSingle();if(again)return again;}throw error;}return data;}

fetchBookings=async function(d){const {data,error}=await db.from("bookings").select("*,booking_participants(id,client_id,participant_order,first_name,last_name,full_name,contact,is_primary)").eq("session_date",d).neq("status","cancelled").order("start_hour");if(error)throw error;return data||[];};
renderBookingGroups=function(){bookingGroups.innerHTML="";if(!bookingsForDay.length){bookingGroups.innerHTML='<div class="empty">No grouped bookings on this date.</div>';return;}bookingsForDay.forEach(b=>{const p=paymentState(b),card=document.createElement("article");card.className="booking-card";const session=b.session_status||"scheduled",roster=(b.booking_participants||[]).sort((a,z)=>a.participant_order-z.participant_order),badge=p.status==="full"?"Paid":p.status==="partial"?"Partial":"Unpaid";const rosterHtml=roster.length?`<div class="booking-roster">${roster.map((x,i)=>`<span class="${i===0?"primary":""}">${i===0?"Primary • ":""}${v17Escape(x.full_name||v17dFull(x))}</span>`).join("")}</div>`:"";card.innerHTML=`<div class="booking-card-top"><div><h4>${v17Escape(b.client_name)} <span class="status-pill-v17 ${v17StatusClass(session)}">${v17SessionLabel(session)}</span></h4><div class="meta">${hourName(Number(b.start_hour))}–${hourName(Number(b.end_hour))} • ${b.participant_count} player(s) • ${v17Escape(b.coaching_type||"")}<br>${b.client_program_id?"Package session":`${b.rate_mode==="custom"?"Custom":"Standard"} rate: ${peso(b.rate_per_person)}/person/hr`}${b.contact?` • ${v17Escape(b.contact)}`:""}</div>${rosterHtml}${b.client_program_id?`<span class="program-line">PROGRAM • Session ${b.program_session_number||"—"}</span>`:""}</div><div class="money">${peso(p.total)}<small>${badge} • Collected ${peso(p.paid)} • Balance ${peso(p.balance)}</small></div></div><div class="booking-actions"><button class="pay-btn" data-act="pay">Record Payment</button><button class="confirm-card-btn" data-act="card">Confirmation Card</button>${b.client_id?'<button class="profile-btn" data-act="profile">Client Profile</button>':''}</div><div class="session-status-actions"></div>`;card.querySelector('[data-act="pay"]').disabled=p.balance<=0;card.querySelector('[data-act="pay"]').onclick=()=>updatePayment(b);card.querySelector('[data-act="card"]').onclick=()=>openConfirmationCard(b);const prof=card.querySelector('[data-act="profile"]');if(prof)prof.onclick=()=>openV17Client(b.client_id);const actions=card.querySelector(".session-status-actions");if(session==="scheduled")[["Completed","complete","completed"],["No Show","noshow","no_show"],["Client Cancelled","clientcancel","client_cancelled"],["Coach Cancelled","coachcancel","coach_cancelled"]].forEach(([txt,cls,st])=>{const bt=document.createElement("button");bt.type="button";bt.className=cls;bt.textContent=txt;bt.onclick=()=>setV17SessionStatus(b,st);actions.appendChild(bt);});bookingGroups.appendChild(card);});};

async function v17dLoadInquiryToBooking(i){if(!i.preferred_date)return alert("This inquiry has no date.");v17dLoadedInquiryId=i.id;v17dLoadedInquiryParticipants=(i.inquiry_participants||[]).sort((a,b)=>a.participant_order-b.participant_order);$("bookingDate").value=i.preferred_date;await loadBookingAvailability();const seed=v17dLoadedInquiryParticipants.length?v17dLoadedInquiryParticipants:[{...v17dSplitLegacyName(i.client_name),contact:i.contact||null}];v17dSetBookingParticipants(seed,i.participant_count||seed.length||1);$("rateMode").value=(Number(i.quoted_rate)===standardRate(i.participant_count||1))?"standard":"custom";updateRate();if($("rateMode").value==="custom"){$("ratePerPerson").readOnly=false;$("ratePerPerson").value=i.quoted_rate||standardRate(i.participant_count||1);}if(i.start_hour!=null&&[...$("bookingStart").options].some(o=>Number(o.value)===i.start_hour)){$("bookingStart").value=String(i.start_hour);const slots=await fetchSlots(i.preferred_date),map=new Map(slots.map(r=>[Number(r.start_hour),r.status]));populateEnd(map);if([...$("bookingEnd").options].some(o=>Number(o.value)===i.end_hour))$("bookingEnd").value=String(i.end_hour);}updateTotal();const bad=await conflictsFor(i.preferred_date,i.start_hour,i.end_hour);if(bad.length)alert("Loaded, but there is a schedule conflict:\n"+bad.join("\n"));$("quickBookingForm").scrollIntoView({behavior:"smooth",block:"start"});}
loadInquiries=async function(){const filter=$("inquiryFilter").value;let q=db.from("inquiries").select("*,inquiry_participants(id,participant_order,first_name,last_name,full_name,contact,is_primary)").order("created_at",{ascending:false});if(filter==="active")q=q.in("status",["new","waiting","tentative"]);else if(filter!=="all")q=q.eq("status",filter);const {data,error}=await q,list=$("inquiryList");if(error){list.innerHTML=`<div class="empty">${v17Escape(error.message)}</div>`;return;}const rows=data||[];$("pendingCount").textContent=rows.filter(x=>["new","waiting","tentative"].includes(x.status)).length;list.innerHTML="";if(!rows.length){list.innerHTML='<div class="empty">No inquiries in this view.</div>';return;}rows.forEach(i=>{const roster=(i.inquiry_participants||[]).sort((a,b)=>a.participant_order-b.participant_order),card=document.createElement("article");card.className="inquiry-card";const rosterHtml=roster.length?`<div class="inquiry-roster">${roster.map((x,n)=>`<span class="${n===0?"primary":""}">${n===0?"Primary • ":""}${v17Escape(x.full_name||v17dFull(x))}</span>`).join("")}</div>`:"";card.innerHTML=`<div class="inquiry-top"><div><h4>${v17Escape(i.client_name)}</h4><div class="inquiry-meta">${i.preferred_date||"No date"}${i.start_hour!=null?` • ${hourName(i.start_hour)}–${hourName(i.end_hour)}`:""} • ${i.participant_count||"?"} player(s)${i.contact?`<br>${v17Escape(i.contact)}`:""}${rosterHtml}${i.goal_focus?`<strong>Goal:</strong> ${v17Escape(i.goal_focus)}<br>`:""}${i.program_interest?`<strong>Program:</strong> ${v17Escape(i.program_interest)}`:""}</div></div><span class="status-pill">${i.status}</span></div><div class="inquiry-actions"><button class="load-btn" type="button">Load to Booking</button><select class="status-select"><option value="new">New</option><option value="waiting">Waiting</option><option value="tentative">Tentative</option><option value="confirmed">Confirmed</option><option value="cancelled">Cancelled</option></select><button class="delete-inquiry" type="button">Delete</button></div>`;card.querySelector(".status-select").value=i.status;card.querySelector(".status-select").onchange=async e=>{await db.from("inquiries").update({status:e.target.value}).eq("id",i.id);toast("Inquiry updated");loadInquiries();};card.querySelector(".delete-inquiry").onclick=async()=>{if(!confirm("Delete this inquiry?"))return;await db.from("inquiries").delete().eq("id",i.id);loadInquiries();};card.querySelector(".load-btn").onclick=()=>v17dLoadInquiryToBooking(i);list.appendChild(card);});};
if($("inquiryFilter"))$("inquiryFilter").onchange=loadInquiries;

$("quickBookingForm").onsubmit=async e=>{e.preventDefault();const d=$("bookingDate").value,s=Number($("bookingStart").value),en=Number($("bookingEnd").value),n=Number($("participantCount").value),entered=v17dCurrentAdminParticipants();if(entered.length!==n||entered.some(p=>!p.first_name||!p.last_name))return alert("Complete the first name and last name of every player.");if(!d||!s||!en||en<=s)return alert("Choose a valid date/time range.");const bad=await conflictsFor(d,s,en);if(bad.length)return alert("Schedule conflict:\n"+bad.join("\n"));const ctx=v17BookingProgramContext;let r=Number($("ratePerPerson").value||0),initial=Number($("amountPaid").value||0),total=(en-s)*n*r;if(ctx){r=0;initial=0;total=0;}else if(initial>total)return alert("Initial payment cannot be higher than the booking total.");
  let linked=[];try{for(let i=0;i<entered.length;i++){const c=(ctx&&i===0)?ctx.client:await v17dResolveClient(entered[i],true);linked.push({...entered[i],client:c,first_name:c.first_name||entered[i].first_name,last_name:c.last_name||entered[i].last_name,full_name:c.full_name||v17dFull(entered[i]),contact:c.contact||entered[i].contact||null});}}catch(err){return alert(`Could not link player profiles.\n\n${err.message}`);}const primary=linked[0],clientId=ctx?.client?.id||primary.client.id;const summary=`Confirm booking?\n\n${linked.map((p,i)=>`Player ${i+1}: ${p.full_name}`).join("\n")}\n\n${d} • ${hourName(s)}–${hourName(en)}\n${n} player(s)${ctx?`\n${ctx.program.name} • Session ${ctx.sessionNumber}/${ctx.program.session_count}\nFixed package — no separate hourly charge`:` • ${peso(r)}/person/hr\nTotal: ${peso(total)}${initial?`\nInitial payment: ${peso(initial)}`:""}`}`;if(!confirm(summary))return;
  const book={session_date:d,start_hour:s,end_hour:en,client_name:primary.full_name,contact:primary.contact,participant_count:n,coaching_type:ctx?ctx.program.name:coachingType(n),rate_mode:ctx?"custom":$("rateMode").value,rate_per_person:r,total_amount:total,amount_paid:0,notes:$("bookingNotes").value.trim()||null,status:"confirmed",client_id:clientId,client_program_id:ctx?.enrollment?.id||null,program_session_number:ctx?.sessionNumber||null,session_status:"scheduled"};const {data:b,error:e1}=await db.from("bookings").insert(book).select().single();if(e1)return alert(e1.message);
  const participantRows=linked.map((p,i)=>({booking_id:b.id,client_id:p.client.id,participant_order:i+1,first_name:p.first_name,last_name:p.last_name,full_name:p.full_name,contact:p.contact,contact_key:v17ContactKey(p.contact),is_primary:i===0}));const {error:pe}=await db.from("booking_participants").insert(participantRows);if(pe){await db.from("bookings").delete().eq("id",b.id);return alert(`Players could not be saved.\n\n${pe.message}`);}const slotRows=[];for(let h=s;h<en;h++)slotRows.push({slot_date:d,start_hour:h,status:"booked",client_name:book.client_name,contact:book.contact,coaching_type:book.coaching_type,rate:r,notes:book.notes,booking_id:b.id});const {error:e2}=await db.from("schedule_slots").insert(slotRows);if(e2){await db.from("bookings").delete().eq("id",b.id);return alert(e2.message);}if(initial>0){const {error:payErr}=await db.from("booking_payments").insert({booking_id:b.id,amount:initial,paid_at:todayStr(),payment_method:"Cash",note:"Initial payment recorded when booking was created",source:"booking_create"});if(payErr){await db.from("schedule_slots").delete().eq("booking_id",b.id);await db.from("bookings").delete().eq("id",b.id);return alert(payErr.message);}}if(v17dLoadedInquiryId){await db.from("inquiries").update({status:"confirmed"}).eq("id",v17dLoadedInquiryId);v17dLoadedInquiryId=null;v17dLoadedInquiryParticipants=[];}toast(ctx?"Program session scheduled":"Booking saved");adminDate.value=d;$("bookingNotes").value="";$("amountPaid").value="0";v17BookingProgramContext=null;$("participantCount").value="1";v17dRenderAdminParticipants(1,[]);$("rateMode").value="standard";updateRate();await Promise.all([loadDay(),loadBookingAvailability(),loadReports(),loadAdminCalendar(),loadInquiries(),loadCollectionAlerts(),loadTodayCommandCenter(),loadPaymentDashboard(),loadV17Clients()]);if(clientId&&v17SelectedClient?.id===clientId)await openV17Client(clientId);};

prepareV17ProgramBooking=function(enrollment,program,nextSession){if(!v17SelectedClient||!program)return;v17BookingProgramContext={enrollment,program,client:v17SelectedClient,sessionNumber:nextSession};$("participantCount").value="1";v17dRenderAdminParticipants(1,[{first_name:v17SelectedClient.first_name||v17dSplitLegacyName(v17SelectedClient.full_name).first_name,last_name:v17SelectedClient.last_name||v17dSplitLegacyName(v17SelectedClient.full_name).last_name,contact:v17SelectedClient.contact||null}]);$("rateMode").value="custom";$("ratePerPerson").readOnly=false;$("ratePerPerson").value="0";$("amountPaid").value="0";updateTotal();$("bookingHint").textContent=`PROGRAM MODE • ${program.name} • Session ${nextSession}/${program.session_count}. This session will not add a separate hourly charge; collection is tracked on the fixed-price package.`;$("quickBookingForm").scrollIntoView({behavior:"smooth",block:"start"});};

if($("clientForm"))$("clientForm").onsubmit=async e=>{e.preventDefault();const first=v17dTitle($("newClientFirstName").value),last=v17dTitle($("newClientLastName").value),contact=v17dClean($("newClientContact").value)||null;if(!first||!last)return alert("First name and last name are required.");const full=v17dFull({first_name:first,last_name:last}),row={first_name:first,last_name:last,full_name:full,name_key:v17dNameKey(first,last),contact,contact_key:v17ContactKey(contact),notes:$("newClientNotes").value.trim()||null};const {data,error}=await db.from("clients").insert(row).select().single();if(error)return alert(error.code==="23505"?"That exact client name + contact is already saved.":error.message);$("clientDialog").close();toast("Client profile created");await loadV17Clients();if(data)openV17Client(data.id);};

openV17Client=async function(id){const client=v17Clients.find(x=>x.id===id)||(await db.from("clients").select("*").eq("id",id).single()).data;if(!client)return;v17SelectedClient=client;$("clientDetailSection").classList.remove("hidden");$("clientDetailName").textContent=client.full_name;$("clientDetailMeta").textContent=[client.contact,client.notes].filter(Boolean).join(" • ")||"No contact or coach notes saved.";const [{data:partRows,error:ppe},{data:primaryRows,error:pbe},{data:enrollments,error:ee},{data:progress,error:pe}]=await Promise.all([db.from("booking_participants").select("booking_id,participant_order").eq("client_id",id),db.from("bookings").select("id").eq("client_id",id),db.from("client_programs").select("*").eq("client_id",id).order("created_at",{ascending:false}),db.from("progress_assessments").select("*").eq("client_id",id).order("assessment_date",{ascending:false}).order("created_at",{ascending:false})]);if(ppe||pbe||ee||pe)return alert((ppe||pbe||ee||pe).message);const orderMap=new Map((partRows||[]).map(x=>[x.booking_id,x.participant_order])),ids=[...new Set([...(partRows||[]).map(x=>x.booking_id),...(primaryRows||[]).map(x=>x.id)])];let bRows=[];if(ids.length){const {data,error}=await db.from("bookings").select("*").in("id",ids).order("session_date",{ascending:false}).order("start_hour",{ascending:false});if(error)return alert(error.message);bRows=(data||[]).map(b=>({...b,_participant_order:orderMap.get(b.id)||1}));}const eRows=enrollments||[],pRows=progress||[],activeBooks=bRows.filter(b=>!v17IsCancelled(b)),completed=activeBooks.filter(b=>b.session_status==="completed"),hours=completed.reduce((a,b)=>a+Number(b.end_hour)-Number(b.start_hour),0),primary=activeBooks.filter(b=>b.client_id===id),bookedValue=primary.reduce((a,b)=>a+Number(b.total_amount||0),0),collected=primary.reduce((a,b)=>a+Number(b.amount_paid||0),0);$("clientDetailStats").innerHTML=[["Completed Sessions",completed.length],["Coaching Hours",hours],["Primary Booking Value",peso(bookedValue)],["Primary Collected",peso(collected)]].map(([a,b])=>`<div class="v17-stat"><span>${a}</span><strong>${b}</strong></div>`).join("");renderV17ClientSessions(bRows);await renderV17ClientPrograms(eRows,bRows);renderV17Progress(pRows);$("clientDetailSection").scrollIntoView({behavior:"smooth",block:"start"});};
renderV17ClientSessions=function(rows){const wrap=$("clientSessionHistory");wrap.innerHTML="";if(!rows.length){wrap.innerHTML='<div class="empty">No linked booking history yet.</div>';return;}rows.slice(0,30).forEach(b=>{const p=paymentState(b),order=Number(b._participant_order||1),el=document.createElement("div");el.className="history-row";el.innerHTML=`<div><strong>${b.session_date}</strong><p>${hourName(Number(b.start_hour))}–${hourName(Number(b.end_hour))}</p></div><div><strong>${v17Escape(b.coaching_type||"Coaching")} <span class="client-role-tag">${order===1?"PRIMARY":"PLAYER "+order}</span></strong><p>${b.client_program_id?`Program session ${b.program_session_number||""} • `:""}${b.client_id===v17SelectedClient?.id?`${peso(b.total_amount)} • Collected ${peso(b.amount_paid)} • Balance ${peso(p.balance)}`:`Group booking • ${b.participant_count} players`}</p></div><span class="status-pill-v17 ${v17StatusClass(b.session_status)}">${v17SessionLabel(b.session_status)}</span>`;wrap.appendChild(el);});};

function v17dParseParticipantLines(text){const rows=[];for(const line of text.split(/\r?\n/)){const m=line.match(/^Player\s+(\d+):\s*(.+?)(?:\s*\|\s*Contact:\s*(.*))?$/i);if(!m)continue;const full=v17dClean(m[2]),sp=v17dSplitLegacyName(full);rows[Number(m[1])-1]={...sp,contact:m[3]&&m[3]!=="Not provided"?v17dClean(m[3]):null};}return rows.filter(Boolean);}
if($("parseBtn"))$("parseBtn").onclick=async()=>{const text=$("pasteInquiry").value.trim(),res=$("parseResult");$("savePendingBtn").disabled=true;parsedInquiry=null;if(!text){res.className="parse-result error";res.textContent="Paste a client message first.";return;}const p=parseClientText(text);if(p.error){res.className="parse-result error";res.textContent=p.error;return;}p.participants=v17dParseParticipantLines(text);if(!p.participants.length){const sp=v17dSplitLegacyName(p.name);p.participants=[{...sp,contact:p.contact||null}];while(p.participants.length<p.players)p.participants.push({first_name:"",last_name:"",contact:null});}parsedInquiry=p;const bad=await conflictsFor(p.date,p.start,p.end);$("bookingDate").value=p.date;await loadBookingAvailability();v17dSetBookingParticipants(p.participants,p.players);$("rateMode").value=p.rate===standardRate(p.players)?"standard":"custom";updateRate();if($("rateMode").value==="custom"){$("ratePerPerson").readOnly=false;$("ratePerPerson").value=p.rate;}if([...$("bookingStart").options].some(o=>Number(o.value)===p.start)){$("bookingStart").value=String(p.start);const slots=await fetchSlots(p.date),map=new Map(slots.map(r=>[Number(r.start_hour),r.status]));populateEnd(map);if([...$("bookingEnd").options].some(o=>Number(o.value)===p.end))$("bookingEnd").value=String(p.end);}updateTotal();$("savePendingBtn").disabled=false;res.className=bad.length?"parse-result error":"parse-result ok";res.innerHTML=bad.length?`<strong>Parsed, but there is a conflict.</strong><br>${bad.join("<br>")}`:`<strong>Available.</strong> ${v17Escape(p.name)} • ${p.date} • ${hourName(p.start)}–${hourName(p.end)} • ${p.players} player(s).`;if(!bad.length)$("quickBookingForm").scrollIntoView({behavior:"smooth",block:"start"});};
if($("savePendingBtn"))$("savePendingBtn").onclick=async()=>{if(!parsedInquiry)return;const p=parsedInquiry,parts=(p.participants||[]).filter(x=>x.first_name&&x.last_name);const primary=parts[0]||{...v17dSplitLegacyName(p.name),contact:p.contact||null};const {data:inq,error}=await db.from("inquiries").insert({client_name:v17dFull(primary),contact:primary.contact||null,preferred_date:p.date,start_hour:p.start,end_hour:p.end,participant_count:p.players,coaching_type:p.coaching,quoted_rate:p.rate,status:"new",source_text:p.source}).select().single();if(error)return alert(error.message);if(parts.length){const {error:ie}=await db.from("inquiry_participants").insert(parts.map((x,i)=>({inquiry_id:inq.id,participant_order:i+1,first_name:v17dTitle(x.first_name),last_name:v17dTitle(x.last_name),full_name:v17dFull(x),contact:x.contact||null,contact_key:v17ContactKey(x.contact),is_primary:i===0})));if(ie)return alert(ie.message);}toast("Pending inquiry saved");await loadInquiries();};

